import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const [avatar, setAvatar] = useState("/assets/default-avatar.png"); // Default avatar

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      try {
        const owner = JSON.parse(ownerData);
        setAvatar(owner.avatar || "/assets/default-avatar.png");
      } catch (error) {
        console.error("Error parsing owner data:", error);
      }
    }

    // Close dropdown when clicking outside
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownVisible(false);
      }
    };

    document.addEventListener("click", handleClickOutside);
    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  useEffect(() => {
    document.body.classList.add("loaded");
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    setIsLoggedIn(false);
    setAvatar("/assets/default-avatar.png");
    navigate("/login"); // Redirect to login after logout
  };

  const toggleDropdown = (event) => {
    event.stopPropagation(); // Prevent closing immediately
    setDropdownVisible((prev) => !prev);
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem("ownerId");
    if (ownerId) {
      navigate(`/profile/${ownerId}`);
    }
  };

  return (
    <nav id="menu" className="navbar navbar-custom">
      <div className="container">
        <div className="navbar-header">
          <button
            type="button"
            className="navbar-toggle collapsed"
            data-toggle="collapse"
            data-target="#bs-navbar"
            aria-expanded="false"
          >
            <span className="sr-only">Toggle navigation</span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
          </button>
          <Link to="/" className="navbar-brand">
            <img src={require("../assets/Logo.png")} alt="Petopia Logo" className="logo" />
          </Link>
        </div>

        <div className="collapse navbar-collapse" id="bs-navbar">
          <ul className="nav navbar-nav navbar-right">
            {!isLoggedIn ? (
              <>
                <li>
                  <Link to="/" className="nav-link">Home</Link>
                </li>
                <li>
                  <Link to="/login" className="nav-link">Log In</Link>
                </li>
              </>
            ) : (
              <li className="dropdown-container" ref={dropdownRef}>
                <img
                  src={avatar}
                  alt="Profile"
                  className="avatar"
                  onClick={toggleDropdown}
                  aria-expanded={dropdownVisible}
                />
                {dropdownVisible && (
                  <div className="dropdown-menu-custom">
                    <div className="dropdown-item" onClick={handleProfileClick}>Profile</div>
                    <div className="dropdown-item" onClick={handleLogout}>Logout</div>
                  </div>
                )}
              </li>
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
};
